const ICON_CATEGORIES = new Set([
  "Languages",
  "Warehouse & modeling",
  "Orchestration & reverse ETL",
  "Cloud",
  "BI",
]);

export function getSkillIcon(skill: string): SkillIconData | undefined {
  return skillIcons[skill];
}

export function categoryUsesSkillIcons(category: string): boolean {
  return ICON_CATEGORIES.has(category);
}
